'use client';

import React, { useEffect, useRef, useState } from 'react';
import AgoraRTC, { IAgoraRTCClient, ILocalVideoTrack, ILocalAudioTrack } from 'agora-rtc-sdk-ng';

const appId = process.env.NEXT_PUBLIC_AGORA_APP_ID!;
const token = process.env.NEXT_PUBLIC_AGORA_TEMP_TOKEN || null;

const CoworkingRoom = () => {
  const [joined, setJoined] = useState(false);
  const [roomId, setRoomId] = useState('');
  const [uid, setUid] = useState<number | undefined>(undefined);

  const localVideoRef = useRef<HTMLDivElement>(null);
  const remoteVideoRef = useRef<HTMLDivElement>(null);

  const clientRef = useRef<IAgoraRTCClient | null>(null);
  const localTracksRef = useRef<[ILocalAudioTrack, ILocalVideoTrack] | []>([]);

  // Generate a unique room ID automatically
  useEffect(() => {
    const generatedRoom = `room-${Math.random().toString(36).substring(2, 8)}`;
    setRoomId(generatedRoom);
  }, []);

  const joinRoom = async () => {
    const client = AgoraRTC.createClient({ mode: 'rtc', codec: 'vp8' });
    clientRef.current = client;

    const uid = await client.join(appId, roomId, token || null);
    setUid(uid);

    const [audioTrack, videoTrack] = await AgoraRTC.createMicrophoneAndCameraTracks();
    localTracksRef.current = [audioTrack, videoTrack];

    if (localVideoRef.current) {
      videoTrack.play(localVideoRef.current);
    }

    await client.publish([audioTrack, videoTrack]);
    setJoined(true);

    client.on('user-published', async (user, mediaType) => {
      await client.subscribe(user, mediaType);
      if (mediaType === 'video' && remoteVideoRef.current) {
        user.videoTrack?.play(remoteVideoRef.current);
      }
      if (mediaType === 'audio') {
        user.audioTrack?.play();
      }
    });
  };

  const leaveRoom = async () => {
    if (!clientRef.current) return;

    localTracksRef.current.forEach(track => track.stop());
    localTracksRef.current.forEach(track => track.close());

    await clientRef.current.leave();
    setJoined(false);
    setUid(undefined);
  };

  return (
    <div className="p-4">
      <h1 className="text-xl font-bold mb-4">Agora Coworking Room</h1>
      <p className="mb-2">Room ID: <strong>{roomId}</strong></p>

      <div className="flex gap-4 mb-4">
        <div ref={localVideoRef} className="w-1/2 border h-64 bg-black" />
        <div ref={remoteVideoRef} className="w-1/2 border h-64 bg-black" />
      </div>

      {!joined ? (
        <button onClick={joinRoom} className="bg-green-500 text-white px-4 py-2 rounded">
          Join Room
        </button>
      ) : (
        <button onClick={leaveRoom} className="bg-red-500 text-white px-4 py-2 rounded">
          Leave Room
        </button>
      )}
    </div>
  );
};

export default CoworkingRoom;
